152	/**
153	 * Place an order: validate, charge the wallet (unless a free admin grant),
154	 * create the Server + PROVISION job. Returns the new server id. Does NOT
155	 * redirect. Callers must ensure funds exist (or pass free) — this still
156	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
157	 */
158	export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
159	  const { plan, os, term, chargeCents, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } =
160	    await orderQuote(intent);
161	  // Note the intro discount on the billing document (first term only; renews full).
162	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
163	
164	  const cap = await capacityCheck(plan.id);
165	  if (!cap.ok) throw new OrderError(cap.reason);
166	
167	  let nodeId: string | null = null;
168	  if (intent.nodeId) {
169	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
170	    if (!n) throw new OrderError("Selected location is not available.");
171	    nodeId = n.id;
172	  } else {
173	    const n = await scheduleNode(plan.ramMB);
174	    nodeId = n?.id ?? null;
175	  }
176	
177	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
178	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
179	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
180	
181	  const addons = {
182	    malwareScanner: !!intent.addonMalware,
183	    dailyBackup: !!intent.addonBackup,
184	    docker: !!intent.addonDocker,
185	  };
186	  const isAdmin = user.role === "ADMIN";
187	  const freeRequested = !!intent.free && isAdmin;
188	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
189	
190	  const newKey = (intent.sshPublicKey ?? "").trim();
191	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
192	
193	  let server;
194	  try {
195	    server = await db.$transaction(async (tx) => {
196	      if (!freeRequested) {
197	        await debitWallet(tx, user.id, chargeCents);
198	        await tx.walletTransaction.create({
199	          data: {
200	            userId: user.id,
201	            amountCents: -chargeCents,
202	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
203	          },
204	        });
205	        // Billing document for the charge — created inside the same debit tx so it
206	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
207	        // Extra disk gets its OWN line so the customer can see exactly what the
208	        // permanent storage costs; the lines always sum back to chargeCents.
209	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
210	        const planLineCents = chargeCents - extraDiskCents;
211	        await tx.invoice.create({
212	          data: invoiceCreateData({
213	            userId: user.id,
214	            description: lineDesc,
215	            status: "PAID",
216	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
217	            lineItems: [
218	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
219	              ...(extraDiskCents > 0
220	                ? [
221	                    {
222	                      description:
223	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
224	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
225	                      qty: 1,
226	                      unitCents: extraDiskCents,
227	                      amountCents: extraDiskCents,
228	                    },
229	                  ]
230	                : []),
231	            ],
232	          }),
233	        });
234	      }
235	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
236	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
237	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
238	      }
239	      const s = await tx.server.create({
240	        data: {
241	          name: intent.hostname,
242	          hostname: intent.hostname,
243	          userId: user.id,
244	          planId: plan.id,
245	          osTemplateId: os.id,
246	          nodeId,
247	          addons,
248	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
249	          // storage for easy restore") and re-confirms it on the Review step, but
250	          // `addons.dailyBackup` was write-only: the worker declares the key and
251	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
252	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
253	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
254	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
255	          // job was ever enqueued. A customer would discover the safety net they
256	          // were promised did not exist at the moment they needed it. Bridge it
257	          // here, at the point of sale.
258	          autoBackup: !!intent.addonBackup,
259	          backupIntervalHours: intent.addonBackup ? 24 : null,
260	          termMonths: term.months,
261	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
262	          // later proration prices the plan delta against this number instead of
263	          // whatever promo happens to be running when the customer clicks resize
264	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
265	          // half of a round trip by choosing the date, and pockets the spread.
266	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
267	          // this scalar and the cash collected describe the same transaction.
268	          // A free admin grant recorded as 100: nothing was paid for these months,
269	          // so nothing may ever prorate out of them.
270	          termPromoPercent: freeRequested ? 100 : promo.discountPercent,
271	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
272	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
273	          // born at its full size, with no separate expansion job.
274	          extraDiskGB,
275	          wantsDedicatedIp: !!intent.dedicatedIp,
276	          isFree: freeRequested,
277	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
278	        },
279	      });
280	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
281	      return s;
282	    });
283	  } catch (e) {
284	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
285	    throw e;
286	  }
287	
288	  await db.auditLog.create({
289	    data: {
290	      userId: user.id,
291	      action: "server.order",
292	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
293	    },
294	  });
295	  if (!freeRequested) {
296	    try {
297	      await maybeRewardReferral(user.id);
298	    } catch {
299	      /* non-fatal */
300	    }
301	  }
302	  return server.id;
303	}

     1	import type { Prisma } from "@prisma/client";
     2	
     3	export class InsufficientBalanceError extends Error {
     4	  constructor() {
     5	    super("INSUFFICIENT_BALANCE");
     6	    this.name = "InsufficientBalanceError";
     7	  }
     8	}
     9	
    10	/**
    11	 * Atomically debit a wallet inside a transaction. The conditional updateMany
    12	 * (balanceCents >= cents) prevents the read-check-then-decrement race that could
    13	 * otherwise drive balances negative under concurrent spend. Throws
    14	 * InsufficientBalanceError (rolling back the tx) if funds are insufficient.
    15	 */
    16	export async function debitWallet(
    17	  tx: Prisma.TransactionClient,
    18	  userId: string,
    19	  cents: number
    20	): Promise<void> {
    21	  if (cents <= 0) return;
    22	  const res = await tx.user.updateMany({
    23	    where: { id: userId, balanceCents: { gte: cents } },
    24	    data: { balanceCents: { decrement: cents } },
    25	  });
    26	  if (res.count === 0) throw new InsufficientBalanceError();
    27	}
=== AUTH ===
     1	import { SignJWT, jwtVerify } from "jose";
     2	import { cookies } from "next/headers";
     3	import { cache } from "react";
     4	import { db } from "./db";
     5	import { getSettingInt } from "./settings";
     6	import type { User } from "@prisma/client";
     7	
     8	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
     9	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
    10	
    11	export async function createSession(userId: string) {
    12	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
    13	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
    14	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
    15	  // Embed the account's current sessionVersion so a bump (password change/reset)
    16	  // invalidates every previously-issued token. Missing => treated as 0.
    17	  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
    18	  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0 })
    19	    .setProtectedHeader({ alg: "HS256" })
    20	    .setIssuedAt()
    21	    .setExpirationTime(`${days}d`)
    22	    .sign(secret);
    23	  const jar = await cookies();
    24	  const secure = process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1";
    25	  jar.set(COOKIE, token, {
    26	    httpOnly: true,
    27	    sameSite: "lax",
    28	    secure,
    29	    maxAge: 60 * 60 * 24 * days,
    30	    path: "/",
    31	  });
    32	  // Non-sensitive, JS-readable flag so the (static) marketing header can show
    33	  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
    34	  // no identity — just presence. Always cleared alongside the session cookie.
    35	  jar.set("nxeon_authed", "1", {
    36	    httpOnly: false,
    37	    sameSite: "lax",
    38	    secure,
    39	    maxAge: 60 * 60 * 24 * days,
    40	    path: "/",
    41	  });
    42	}
    43	
    44	export async function destroySession() {
    45	  const jar = await cookies();
    46	  jar.delete(COOKIE);
    47	  jar.delete("nxeon_authed");
    48	}
    49	
    50	/**
    51	 * Lightweight "is there a valid session?" check — verifies the session JWT
    52	 * (signature + expiry) WITHOUT a DB round-trip. Used by /api/auth/status so the
    53	 * (static) marketing header can authoritatively show "Back to portal" even when
    54	 * the non-httpOnly `nxeon_authed` flag cookie is missing or stale.
    55	 */
    56	export async function isSignedIn(): Promise<boolean> {
    57	  const jar = await cookies();
    58	  const token = jar.get(COOKIE)?.value;
    59	  if (!token) return false;
    60	  try {
    61	    await jwtVerify(token, secret);
    62	    return true;
    63	  } catch {
    64	    return false;
    65	  }
    66	}
    67	
    68	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
    69	
    70	/** The real signed-in account, ignoring any impersonation. */
    71	export const realUser = cache(async (): Promise<User | null> => {
    72	  const jar = await cookies();
    73	  const token = jar.get(COOKIE)?.value;
    74	  if (!token) return null;
    75	  try {
    76	    const { payload } = await jwtVerify(token, secret);
    77	    if (!payload.sub) return null;
    78	    const user = await db.user.findUnique({ where: { id: payload.sub } });
    79	    if (!user || user.suspended) return null;
    80	    // Session revocation: a token is only valid while its embedded version matches
    81	    // the account's current sessionVersion. Older tokens without `sv` count as 0,
    82	    // so accounts that never bumped stay logged in (backward-compatible).
    83	    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
    84	    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
    85	    return user;
    86	  } catch {
    87	    return null;
    88	  }
    89	});
    90	
    91	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
    92	export const currentUser = cache(async (): Promise<User | null> => {
    93	  const real = await realUser();
    94	  if (!real) return null;
    95	  if (real.role === "ADMIN") {
    96	    const jar = await cookies();
    97	    const imp = jar.get(IMP_COOKIE)?.value;
    98	    if (imp) {
    99	      try {
   100	        const { payload } = await jwtVerify(imp, secret);
   101	        if (payload.adminId === real.id && typeof payload.sub === "string") {
   102	          const target = await db.user.findUnique({ where: { id: payload.sub } });
