513	  await assertNotImpersonating();
514	  // Security: never mint free wallet balance in production. The demo gateway that
515	  // credits without a real payment is only ever acceptable in non-production, and
516	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
517	  if (process.env.NODE_ENV === "production") {
518	    return { error: "Please add funds with a card via the secure checkout." };
519	  }
520	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
521	  // go through Checkout.
522	  const { stripeConfigured } = await import("./stripe");
523	  if (stripeConfigured()) {
524	    return { error: "Please add funds with a card via the secure checkout." };
525	  }
526	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
527	  const topupHdrs = await headers();
528	  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
529	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
530	  if (!topupRl.ok) {
531	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
532	  }
