534	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
535	    return { error: "Amount must be between $1 and $1000." };
536	  }
537	  const cents = Math.round(amount * 100);
538	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
539	  const minTopup = await getSettingInt("min_topup_cents", 500);
540	  if (cents < minTopup) {
541	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
542	  }
543	
544	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
545	  // sets. applyCouponToTopup re-validates for this user against the real amount.
546	  const jar = await cookies();
547	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
548	  let bonusCents = 0;
549	  let couponId: string | null = null;
550	  let couponLabel = "";
551	  if (couponCode) {
552	    const result = await applyCouponToTopup(couponCode, cents);
553	    if (result.ok) {
554	      bonusCents = result.bonusCents;
555	      couponId = result.couponId;
556	      couponLabel = result.label;
557	    } else {
558	      // REFUSE, don't silently drop. The old code fell through and completed the
559	      // top-up with no bonus and no message, so a code that passed validation at
560	      // the preview amount but fails against the real one (a `minAmountCents`
561	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
562	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
563	      // charged at this point, so stopping is free and the customer can retry
564	      // without the code or with a larger amount.
565	      return {
566	        error:
567	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
568	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
569	      };
570	    }
571	  }
572	
573	  await db.$transaction([
574	    db.user.update({
575	      where: { id: user.id },
576	      data: { balanceCents: { increment: cents + bonusCents } },
577	    }),
578	    db.walletTransaction.create({
579	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
580	    }),
581	    ...(bonusCents > 0 && couponId
582	      ? [
583	          db.walletTransaction.create({
584	            data: {
585	              userId: user.id,
586	              amountCents: bonusCents,
587	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
588	            },
589	          }),
