623	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
624	  // Spend path: block wallet debits while an admin is impersonating.
625	  await assertNotImpersonating();
626	  const { user, server } = await ownedServer(serverId);
627	  if (server.isFree || !server.expiresAt) return;
628	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
629	  if (!plan) return;
630	  const term = vpsTerm(server.termMonths);
631	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
632	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
633	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
634	    where: { serverId }, select: { id: true },
635	  }));
636	  // Extra root disk renews at the current per-GB price on top of the plan, exactly
637	  // like worker/billing.ts — the two renewal paths must never disagree.
638	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
639	  const extraDiskCents = extraDiskMonthly * term.months;
640	  // Priced through the SHARED quote so the figure on the button is the figure
641	  // taken from the wallet. See lib/renewal-quote.ts for the incident that turned
642	  // this into one function instead of two copies of the same arithmetic.
643	  const renewCents = renewalQuote({
644	    planPriceCents: plan.priceCents,
645	    termMonths: server.termMonths,
646	    hasDedicatedIp,
647	    dedicatedIpMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
648	    extraDiskMonthlyCents: extraDiskMonthly,
649	  }).totalCents;
650	  const owner = await db.user.findUnique({ where: { id: server.userId } });
651	  if (!owner || owner.balanceCents < renewCents) {
652	    return { error: "Insufficient balance — top up your wallet first." };
653	  }
654	
655	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
656	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
657	  // can't both read E, both debit, and both write E+term (double-charge, one
658	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
659	  const E = server.expiresAt;
660	  const base = new Date(Math.max(E.getTime(), Date.now()));
661	  const newExpiry = addMonths(base, term.months);
662	
663	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
664	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
665	  // strikethrough on the marketing page is the real renewal price. So the months
666	  // being added here are sold at 0% off, and the term's stored rate has to say so.
667	  //
668	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
669	  // term on top of months still running at an intro discount. Overwriting would
670	  // silently reprice those earlier months to full list — and that is the profitable
671	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
672	  // the original discounted months would suddenly credit at the full rate on a
673	  // downgrade. Blending keeps the cash value of the window invariant.
674	  const renewedPercent = prorateBlendPercent({
675	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
676	    currentMonths: remainingMonths(E, Date.now()),
677	    addedPercent: 0,
678	    addedMonths: term.months,
679	  });
680	  try {
681	    await db.$transaction(async (tx) => {
682	      // Compare-and-swap the expiry first; if it no longer equals E another
683	      // renewal already advanced it — bail without charging (tx rolls back).
684	      const adv = await tx.server.updateMany({
685	        where: { id: serverId, expiresAt: E },
686	        data: {
687	          expiresAt: newExpiry,
688	          termPromoPercent: renewedPercent,
689	          suspendedNote: null,
690	          suspendReason: null,
691	        },
692	      });
693	      if (adv.count === 0) throw new AlreadyRenewedError();
