697	        data: {
698	          userId: server.userId,
699	          amountCents: -renewCents,
700	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
701	        },
702	      });
703	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
704	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
