706	        data: invoiceCreateData({
707	          userId: server.userId,
708	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
709	          status: "PAID",
710	          period: { start: E, end: newExpiry },
711	          lineItems: [
712	            {
713	              description: `${plan.name} VPS (${server.hostname}) — ${term.label}`,
714	              qty: 1,
715	              unitCents: renewCents - extraDiskCents,
