83	  const parsed = credsSchema
84	    .extend({
85	      name: z.string().min(1).max(100),
86	      password: z
87	        .string()
88	        .min(8, "Password must be at least 8 characters")
89	        .max(200)
90	        .regex(/[a-zA-Z]/, "Password must include a letter")
91	        .regex(/[0-9]/, "Password must include a number"),
92	    })
93	    .safeParse({
94	    email: formData.get("email"),
95	    password: formData.get("password"),
96	    name: formData.get("name"),
97	  });
98	  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
99	  const { email, password, name } = parsed.data;
100	
101	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
102	  // automated account creation and welcome-credit farming.
103	  const regHdrs = await headers();
104	  const regIp = (regHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
105	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
106	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
107	
108	  const existing = await db.user.findUnique({ where: { email } });
109	  if (existing) return { error: "An account with that email already exists." };
110	
111	  // Capture a referral from the `ref` cookie (set by the register page) if the
112	  // code maps to a real user. Self-referral is impossible here (new account).
113	  const jar = await cookies();
114	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
115	  let referredById: string | null = null;
116	  if (refCode) {
117	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
118	    if (referrer) referredById = referrer.id;
119	  }
120	
121	  const referralCode = await uniqueReferralCode();
122	  const user = await db.user.create({
123	    data: {
124	      email,
125	      name,
126	      passwordHash: await bcrypt.hash(password, 12),
127	      referralCode,
128	      referredById,
129	    },
130	  });
131	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
132	  // Establish the session first so the freshly-created account is the acting user
133	  // when grantSignupCredit runs (its internal guard requires self-attribution).
134	  await createSession(user.id);
135	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
136	  try {
137	    await grantSignupCredit(user.id);
138	  } catch { /* non-fatal */ }
139	  jar.delete(REF_COOKIE);
140	  try {
141	    const { sendMail, emails } = await import("./mailer");
142	    const tpl = emails.welcome(name);
143	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
144	  } catch { /* email is best-effort */ }
145	  redirect("/dashboard");
146	}
